(()=>{const A='#c69b72',reduce=matchMedia('(prefers-reduced-motion:reduce)').matches,b=document.body,s=document.createElement('style');s.textContent=`.fxbar{position:fixed;top:0;left:0;width:100%;height:2px;background:#0001;z-index:100}.fxbar i{display:block;height:100%;width:0;background:${A};box-shadow:0 0 14px ${A}}.fx-orb{position:fixed;border-radius:50%;pointer-events:none;filter:blur(85px);opacity:.12;z-index:-1}.fx-orb.a{width:360px;height:360px;left:-140px;top:15%;background:${A};animation:drift 14s ease-in-out infinite}.fx-orb.b{width:320px;height:320px;right:-130px;bottom:10%;background:#8c6f57;animation:drift 18s ease-in-out infinite reverse}.fx-leaf{position:fixed;width:10px;height:16px;border-radius:90% 10% 90% 10%;background:linear-gradient(135deg,#d9ae73,#8e6949);box-shadow:0 0 10px #d9ae7333;pointer-events:none;z-index:2;opacity:0;animation:leafFall linear infinite}.fx-mote{position:fixed;width:3px;height:3px;border-radius:50%;background:#e5c28f;box-shadow:0 0 12px #e5c28faa;pointer-events:none;z-index:2;opacity:0;animation:moteFloat ease-in-out infinite}.fxr{opacity:0;transform:translateY(40px);transition:1s cubic-bezier(.2,.8,.2,1)}.fxr.on{opacity:1;transform:none}.timeline .reel-wrap{position:relative}.developed{transition:box-shadow .4s}.future-saved:after{content:'∞';position:fixed;inset:0;display:grid;place-items:center;z-index:80;pointer-events:none;font:180px 'Playfair Display';color:${A};text-shadow:0 0 50px #c69b7266;animation:future .95s ease both}@keyframes drift{50%{transform:translate(80px,-45px)}}@keyframes leafFall{0%{transform:translate3d(0,-12vh,0) rotate(0deg);opacity:0}12%{opacity:.65}35%{transform:translate3d(45px,25vh,0) rotate(105deg)}65%{transform:translate3d(-35px,58vh,0) rotate(225deg);opacity:.45}100%{transform:translate3d(55px,112vh,0) rotate(360deg);opacity:0}}@keyframes moteFloat{0%,100%{transform:translate3d(0,12px,0) scale(.5);opacity:0}25%{opacity:.55}50%{transform:translate3d(18px,-18px,0) scale(1.1);opacity:.8}75%{transform:translate3d(-12px,-38px,0) scale(.7);opacity:.35}}@keyframes future{0%{opacity:0;transform:scale(.6)}50%{opacity:1;transform:scale(1.08)}100%{opacity:0;transform:scale(1.3)}}`;b.appendChild(s);const bar=document.createElement('div');bar.className='fxbar';bar.innerHTML='<i></i>';b.appendChild(bar);['a','b'].forEach(c=>{const o=document.createElement('div');o.className='fx-orb '+c;b.appendChild(o)});if(!reduce){for(let i=0;i<16;i++){const p=document.createElement('i');p.className='fx-leaf';p.style.left=(3+Math.random()*94)+'%';p.style.top=(-15-Math.random()*20)+'vh';p.style.animationDelay=(-Math.random()*12)+'s';p.style.animationDuration=(10+Math.random()*8)+'s';p.style.transformOrigin='50% 50%';b.appendChild(p)}for(let i=0;i<18;i++){const p=document.createElement('i');p.className='fx-mote';p.style.left=(5+Math.random()*90)+'%';p.style.top=(12+Math.random()*78)+'%';p.style.animationDelay=(-Math.random()*7)+'s';p.style.animationDuration=(4+Math.random()*4)+'s';b.appendChild(p)}}document.querySelectorAll('section').forEach(e=>e.classList.add('fxr'));const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('on');io.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.fxr').forEach(e=>io.observe(e));addEventListener('scroll',()=>{const m=document.documentElement.scrollHeight-innerHeight;bar.firstElementChild.style.width=(m?scrollY/m*100:0)+'%'})})();